package app.getknit.knit.data.emoji

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File
import java.util.Locale

/**
 * Contract test for the shipped `emoji/emoji_<tag>.tsv` overlays (generated by `scripts/gen-emoji-catalog.py`
 * from the vendored CLDR locales), read from disk and parsed with the production parser like
 * [EmojiCatalogAssetTest]: every row parses, names only emoji the catalog has, in its order, and every app
 * language under `res/values-<locale>/` lands on an overlay.
 */
class EmojiOverlayAssetTest {
    private val module: File by lazy {
        listOf(File("."), File("app")).firstOrNull { File(it, "src/main/assets/emoji/emoji_en.tsv").exists() }
            ?: error("app module not found (cwd=${File(".").absolutePath})")
    }
    private val assetDir: File by lazy { File(module, "src/main/assets/emoji") }
    private val english: EmojiCatalog by lazy {
        EmojiCatalog(File(assetDir, "emoji_en.tsv").bufferedReader().useLines(EmojiCatalogParser::parse))
    }
    private val tags: Set<String> by lazy { EmojiLocales.tagsIn(assetDir.list().orEmpty().toList()) }

    private fun overlayFile(tag: String) = File(assetDir, "emoji_$tag.tsv")

    private fun overlay(tag: String) = overlayFile(tag).bufferedReader().useLines(EmojiCatalogParser::parseOverlay)

    @Test
    fun everyAppLanguageHasAnOverlay() {
        // The first qualifier of a values- folder is its locale when it is one: `de`, `pt-rBR` (the two-part
        // form) or `b+es+419` (BCP 47). Anything else there (night, v31, land, sw600dp) is no language.
        val languages =
            File(module, "src/main/res")
                .list()
                .orEmpty()
                .filter { it.startsWith("values-") }
                .mapNotNull { dir -> localeOf(dir.removePrefix("values-")) }
                .filter { Locale.forLanguageTag(it).language != "en" } // English is the base catalog
        assertTrue("no values-<locale> directories found", languages.isNotEmpty())
        languages.forEach { lang ->
            assertNotNull("values-$lang has no emoji overlay in $tags", EmojiLocales.overlayFor(listOf(lang), tags))
        }
    }

    @Test
    fun theValuesFolderReaderKnowsEveryLocaleForm() {
        assertEquals("pt-BR", localeOf("pt-rBR"))
        assertEquals("es-AR", localeOf("es-rAR-v31"))
        assertEquals("de", localeOf("de"))
        assertEquals("es-419", localeOf("b+es+419"))
        assertEquals(null, localeOf("night"))
        assertEquals(null, localeOf("v31"))
        assertEquals(null, localeOf("sw600dp"))
    }

    @Test
    fun everyRowParsesAndNamesACatalogEmojiInCatalogOrder() {
        val order = english.entries.withIndex().associate { (i, e) -> e.emoji to i }
        assertTrue("expected the shipped overlays, got $tags", tags.size >= 6)
        tags.forEach { tag ->
            val rows = overlayFile(tag).readLines().filter { '\t' in it }
            val parsed = overlay(tag)
            assertEquals("$tag: a dropped row", rows.size, parsed.size)
            assertTrue("$tag: names under 90 % of the catalog", parsed.size >= english.entries.size * 9 / 10)
            val positions =
                rows.map {
                    order[
                        it.substringBefore(
                            '\t',
                        ),
                    ] ?: error("$tag: '${it.substringBefore('\t')}' is not in the catalog")
                }
            assertEquals("$tag: rows out of catalog order", positions.sorted(), positions)
            parsed.forEach { (emoji, l) ->
                assertTrue(
                    "$tag: blank or separator-bearing keyword on $emoji",
                    l.keywords.all { k ->
                        k.isNotBlank() &&
                            k.none { it in SEPARATORS }
                    },
                )
                assertTrue("$tag: separator in the name of $emoji", l.name.none { it in SEPARATORS })
            }
        }
    }

    @Test
    fun toneVariantsCarryNoKeywordsInAnyLanguage() {
        val tones =
            english.entries
                .filter { it.toneVariant }
                .map { it.emoji }
                .toSet()
        tags.forEach { tag ->
            val withKeywords = overlay(tag).filter { (emoji, l) -> emoji in tones && l.keywords.isNotEmpty() }.keys
            assertTrue("$tag: tone variants with keywords: ${withKeywords.take(5)}", withKeywords.isEmpty())
        }
    }

    @Test
    fun aLocalizedCatalogAnswersInItsLanguageAndInEnglish() {
        val pt = english.localized(overlay("pt"))
        assertEquals("👍", pt.search("polegar para cima").first().emoji)
        assertEquals("👍", pt.search("thumbs up").first().emoji)
        val es = english.localized(overlay("es"))
        assertEquals("❤️", es.search("corazon rojo").first().emoji)
        val uk = english.localized(overlay("uk"))
        assertEquals("червоне серце", uk.entries.first { it.emoji == "❤️" }.name)
    }

    /** The BCP 47 tag a values- folder's qualifiers start with, or null when they start with something else. */
    private fun localeOf(qualifiers: String): String? {
        val parts = qualifiers.split('-')
        if (parts[0].startsWith("b+")) return parts[0].removePrefix("b+").replace('+', '-')
        if (!LANGUAGE.matches(parts[0])) return null
        val region = parts.getOrNull(1)?.takeIf { REGION.matches(it) }?.removePrefix("r")
        return if (region == null) parts[0] else "${parts[0]}-$region"
    }

    private companion object {
        val LANGUAGE = Regex("[a-z]{2,3}")
        val REGION = Regex("r[A-Z]{2}")
        val SEPARATORS = setOf('\t', '\n', '|', RecentReactions.SEPARATOR)
    }
}
